var sums = new long[8];          // 64 байта: соседи в одной кэш-линии
Parallel.For(0, 8, t =>
{
    for (int i = 0; i < 100_000_000; i++)
        sums[t]++;               // гонки нет, а линия мечется
});

// лечение: локальный итог, одна запись в конце
Parallel.For(0, 8, t =>
{
    long local = 0;
    for (int i = 0; i < 100_000_000; i++) local++;
    sums[t] = local;
});
